[
  {
    "sys_consistent_procedure": "work these things out the same way every time",
    "sys_consequence_reasoning": "count the years everyone loses and choose the smaller total",
    "pd_harm_distress": "I hate where it leaves me",
    "sys_rule_justification": "would be a hypocrite to drop it now"
  },
  {
    "sys_consistent_procedure": "rule has been the same for as long as I can remember",
    "sys_rule_justification": "I don't hand another person over",
    "pd_harm_distress": "not pretending it doesn't sink my stomach"
  },
  {
    "sys_consistent_procedure": "That's where I always land, and I lean on it here",
    "sys_rule_justification": "If I'm asked what happened, I answer truthfully",
    "ce_understood_harm": "puts three years on someone who'd otherwise walk free",
    "pd_harm_distress": "that sits heavy with me"
  },
  {
    "sys_consistent_procedure": "I stick to that even when waiting feels awful",
    "sys_rule_justification": "I don't choose until I can",
    "pd_decision_conflict": "When two choices both hurt someone and I can't honestly say"
  },
  {
    "sys_consistent_procedure": "Whenever I'm stuck, I picture everyone who knows me hearing exactly",
    "pd_harm_distress": "It's a sad little outcome either way"
  },
  {
    "sys_consistent_procedure": "I always ask one thing",
    "sys_consequence_reasoning": "If I can keep it on mine alone, I do",
    "ce_understood_harm": "drags someone else into three years they wouldn't otherwise serve",
    "pd_personal_consequence_anxiety": "Five years is a long, dull ache to think about"
  },
  {
    "sys_consistent_procedure": "question I put to every hard decision is this",
    "sys_fairness_reciprocity": "would I want anybody standing where I'm standing to do the same",
    "ce_understood_harm": "other person serves three years instead of none",
    "pd_harm_distress": "I don't feel good about that"
  },
  {
    "sys_consistent_procedure": "just go along with the lawful process when it asks",
    "pd_harm_distress": "no contact afterward, which somehow makes it lonelier"
  },
  {
    "sys_consistent_procedure": "For me there's one test",
    "sys_consequence_reasoning": "would my choice leave someone worse off than they'd be",
    "ce_understood_harm": "If I speak, the other person loses three years",
    "pd_personal_consequence_anxiety": "The years ahead feel long and grey just thinking about them"
  },
  {
    "sys_consistent_procedure": "That's the line I've always drawn, and I measure choices",
    "sys_rule_justification": "never trade someone else's freedom for a piece of mine",
    "pd_harm_distress": "It's a heavy thing to accept"
  }
]
